module typed_origin;
struct Box<T>{value:T;}
enum Failure{Missing(path:str);Denied(code:i64);}
fn error(value:i64)->i64{return value;}
fn payload(value:i64)->Box<i64>{return Box(value+1);}
fn main()->unit !{task,throw,io}{
 let domain:Failure=Failure::Missing("data");assert(domain==Failure::Missing("data"));
 var value:i64=0;
 try{let held:Box<i64>=payload(error(40));value=held.value;task_yield();throw("APP","λ\u0000🙂");}
 catch(code,message) if code=="APP"{assert(message=="λ\u0000🙂");}
 finally{task_yield();value=value+1;}
 print(value);
}

